const initial={theme:'light',read:[],practiced:[],assignments:[],passed:[],mastered:[],assessmentPassed:false,bookmarks:[],notes:{},studyPlan:{},journal:[],passport:[],strategy:[],friend:[],watchlist:DEFAULT_WATCHLIST.map(x=>({...x})),paperTrades:[],equity:10000,paperEquityCurve:[10000],lesson:1,customLessons:[],misconceptions:[],researchInbox:[],savedQuestions:[],experiments:[],testConsumed:false,assistantMemory:[],btPaperOrders:[],btPaperStartingEquity:10000,firstSession:[]};
let state=loadState(), courseText='';
function loadState(){return AcademyMath.loadState(localStorage,KEY,initial)}
