function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function fmt(n,d=2){return Number.isFinite(+n)?new Intl.NumberFormat('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}).format(+n):'—'}
function cash(n,d=2){return '$'+fmt(n,d)}
function fmtPrice(p){if(!Number.isFinite(+p))return '—';const v=+p;if(v<0)return '-'+fmtPrice(Math.abs(v));if(v>=1000)return '$'+new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v);if(v>=1)return '$'+v.toFixed(2);if(v>=0.01)return '$'+v.toFixed(4);if(v>0)return '$'+v.toFixed(8).replace(/0+$/,'');return '$0.00';}
function fmtQty(q){if(!Number.isFinite(+q))return '—';const v=+q;if(v>=1000)return new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(v);if(v>=1)return v.toFixed(4).replace(/\.?0+$/,'');return v.toFixed(6).replace(/\.?0+$/,'');}
function toast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function applyTheme(){document.documentElement.dataset.theme=state.theme==='dark'?'dark':'light'}
async function init(){applyTheme();try{const t1=await(await fetch('content/part-1.md')).text();let t2='';try{const r2=await fetch('content/part-2-quant-strategies.md');if(r2.ok)t2=await r2.text()}catch{}courseText=t2?t1+'\n\n'+t2:t1}catch{courseText='Unable to load course content. Run the local server from the app folder.'}route()}
function route(){const [view,arg]=location.hash.replace(/^#/,'').split('/');const name=view||'home';if(window._paperTickTimer&&name!=='paper'){clearInterval(window._paperTickTimer);window._paperTickTimer=null;}document.querySelectorAll('#navigation a').forEach(a=>a.classList.toggle('active',a.dataset.view===name));const active=document.querySelector(`#navigation a[data-view="${name}"]`), group=active?.dataset.navGroup;document.querySelectorAll('#navigation .nav-group').forEach(d=>{d.open=d.dataset.navGroup===group});$('#crumb').textContent=`ACADEMY / ${name.replaceAll('-',' ').toUpperCase()}`;$('#sidebar').classList.remove('open');$('.mobile-overlay')?.classList.remove('show');render(name,arg);window.scrollTo(0,0)}
