function home(){const done=state.mastered.length, next=Math.min(4,done+1), routeSteps=[{id:'mechanics',n:'01',title:'Learn one mechanic',detail:'Read the first lesson on exposure and margin.',href:'#lesson/1',cta:'Open lesson'},{id:'sizing',n:'02',title:'Work a sizing example',detail:'Try a deterministic risk-sizing exercise with hypothetical inputs.',href:'#sizing',cta:'Open sizing tool'},{id:'orders',n:'03',title:'Practice an order decision',detail:'Compare order behavior in the paper sandbox. No broker is connected.',href:'#orders',cta:'Practice an order'}], sessionDone=(state.firstSession||[]).length;app.innerHTML=`<div class="eyebrow">TRADING RESEARCH ACADEMY · PART 1</div><div class="hero"><div><h1>Understand exposure.<br>Test ideas. Earn your conclusions.</h1><p>Welcome, Sarthak. Learn the mechanics first, then practice a decision, then decide whether an idea is specific enough to test. This is an educational workspace—not a trading dashboard.</p><div class="actions"><a class="button" href="#lesson/${next}">Continue learning <span>→</span></a><a class="button secondary" href="#course">View course map</a></div></div><div class="hero-card"><small>START WITH THE BASICS</small><strong>Account equity, exposure, collateral and planned loss are different quantities.</strong><span>Use paper trading for assignments. Simulation is not evidence of live profitability.</span></div></div><section class="first-session" aria-labelledby="first-session-title"><div class="row between"><div><div class="eyebrow">A SIMPLE FIRST SESSION · ABOUT 15 MINUTES</div><h2 id="first-session-title">A clear path through the workspace</h2><p class="muted">Start with mechanics. Nothing here places a live order.</p></div><span class="status neutral">${sessionDone}/3 checked by you</span></div><div class="first-session-steps">${routeSteps.map((s,i)=>`<article class="first-step ${state.firstSession?.includes(s.id)?'is-done':''}"><div class="first-step-top"><span class="step-number">${s.n}</span><div><h3>${s.title}</h3><p>${s.detail}</p></div></div><div class="actions"><a class="button secondary small" href="${s.href}">${s.cta} →</a><button class="text-button" type="button" onclick="toggleFirstSession('${s.id}')" aria-pressed="${state.firstSession?.includes(s.id)||false}">${state.firstSession?.includes(s.id)?'✓ Marked complete':'Mark complete when you finish'}</button></div></article>`).join('')}</div></section><div class="grid grid-3 home-metrics"><div class="card"><div class="metric">${state.mastered.length}/4</div><div class="metric-label">Part 1 mastery checkpoints</div><div class="progress-track"><span style="width:${state.mastered.length/4*100}%"></span></div></div><div class="card"><div class="metric">Part 1</div><div class="metric-label">Available course material</div><p class="tiny">Exposure, products, orders, margin and basic sizing.</p></div><div class="card"><div class="metric">0</div><div class="metric-label">Live connections</div><p class="tiny">No brokerage, exchange, or trade execution integrations.</p></div></div><h2 class="section-title">Your next step</h2><div class="grid grid-2"><div class="card"><div class="row between"><div><h3>Lesson ${next}: ${lessonTitle(next)}</h3><p>Read, work the examples, then try the quiz and checkpoint.</p></div><span class="status">Available</span></div><a class="button small" href="#lesson/${next}">Open lesson</a></div><div class="card"><h3>Next unfinished assignment</h3><p>${next===1?'Annotate a simulated order ticket: equity, symbol, quantity, notional, leverage setting and margin.':`Complete Lesson ${next}'s assignment and record your work in the relevant worksheet.`}</p><a class="button secondary small" href="#lesson/${next}">Review assignment</a></div></div><section class="home-research-path"><div><div class="eyebrow">WHEN YOU ARE READY</div><h2>Research before you test</h2><p>Capture a source, write observable rules, check the data and assumptions, then run an educational backtest. The lab needs your own suitable CSV data; it does not quietly substitute sample or live prices.</p></div><div class="actions"><a class="button secondary" href="#inbox">Capture an idea</a><a class="button" href="#backtest">Open backtesting lab</a></div></section><div class="notice">A simulation can help you learn mechanics. It cannot establish achievable live execution, custody, or profitability.</div><h2 class="section-title">Course availability</h2>${courseStatus()}`}
function toggleFirstSession(id){state.firstSession=state.firstSession||[];state.firstSession=state.firstSession.includes(id)?state.firstSession.filter(x=>x!==id):[...state.firstSession,id];save();home()}
const titles=['Exposure is not margin','Read the product before the chart','Orders control different things','Size from planned loss, not buying power','Multi-Asset Momentum & The Rotation Index','The RiskLens Framework: Downside Risk, Cornish-Fisher VaR & Volatility Targeting','Systematic Execution, Stop Loss / Take Profit Mechanics & Paper Trading','Parameter Optimization & Avoiding Overfitting'];function lessonTitle(n){return titles[(n-1)%titles.length]||'Part 1 assessment'}
function courseStatus(){return `<div class="grid grid-2"><div class="card"><div class="row between"><h3>Core curriculum</h3><span class="status">Parts 1 & 2 available</span></div><p><b>Part 1 · Available:</b> Exposure, products, orders, margin and basic sizing (Lessons 1–4).</p><p><b>Part 2 · Available:</b> Multi-asset momentum rotation, RiskLens downside risk/VaR, systematic execution, and parameter optimization (Lessons 5–8).</p><p><b>Part 3 · Awaiting material:</b> Institutional liquidity, market microstructure, and high-frequency order book dynamics.</p><p><b>Part 4 · Awaiting material:</b> Automated live execution bridges, algorithmic routing, and broker API integration.</p><p><b>Part 5 · Awaiting material:</b> Discipline, current U.S./California safeguards, tax introduction, complete friend-strategy rubric and graduation assessment.</p></div><div class="card"><div class="row between"><h3>Advanced electives</h3><span class="status">Quantitative suite ready</span></div><p>Multi-Asset Rotation Index (RAPM), RiskLens Cornish-Fisher analytics, and Vektor backtesting & overfitting diagnostics are fully integrated.</p><p class="tiny">Options volatility surfaces and high-frequency bridges remain awaiting future modules.</p></div></div>`}
function course(){app.innerHTML=`<div class="page-head"><div class="eyebrow">YOUR LEARNING PATH</div><h1>Course map</h1><p>Progress records reading, practice, assignment, quiz performance and demonstrated mastery separately. Opening a lesson never counts as mastery. You can review any available lesson at any time.</p></div>${courseStatus()}<h2 class="section-title">Part 1 · Exposure, products, orders, margin and basic sizing</h2><div class="lesson-list">${titles.slice(0,4).map((t,i)=>`<a class="lesson-row" href="#lesson/${i+1}"><span class="lesson-number">0${i+1}</span><span><b>${esc(t)}</b><small>${state.read.includes(i+1)?'Read':'Not read'} · ${state.practiced.includes(i+1)?'Practiced':'Not practiced'} · Assignment ${state.assignments.includes(i+1)?'complete':'not complete'} · ${state.passed.includes(i+1)?'Quiz passed':'quiz not passed'}</small></span><span class="status ${state.mastered.includes(i+1)?'':'neutral'}">${state.mastered.includes(i+1)?'Mastery shown':'Available'}</span></a>`).join('')}</div><div class="card"><div class="row between"><div><h3>Part 1 assessment</h3><p>${state.assessmentPassed?'Assessment passed':'Not yet passed'}</p></div><span class="status ${state.assessmentPassed?'':'neutral'}">${state.assessmentPassed?'Passed':'Available'}</span><a class="button secondary small" href="#assessment">Open assessment</a></div></div><h2 class="section-title">Part 2 · Advanced Quantitative Strategies</h2><div class="lesson-list">${titles.slice(4).map((t,i)=>`<a class="lesson-row" href="#lesson/${i+5}"><span class="lesson-number">0${i+5}</span><span><b>${esc(t)}</b><small>${state.read.includes(i+5)?'Read':'Not read'} · ${state.practiced.includes(i+5)?'Practiced':'Not practiced'} · Assignment ${state.assignments.includes(i+5)?'complete':'not complete'} · ${state.passed.includes(i+5)?'Quiz passed':'quiz not passed'}</small></span><span class="status ${state.mastered.includes(i+5)?'':'neutral'}">${state.mastered.includes(i+5)?'Mastery shown':'Available'}</span></a>`).join('')}</div>${state.customLessons.length?`<h2 class="section-title">Imported lessons</h2><div class="lesson-list">${state.customLessons.map(x=>`<a class="lesson-row" href="#custom/${encodeURIComponent(x.id)}"><span class="lesson-number">+</span><span><b>${esc(x.title)}</b><small>Part ${esc(x.part||'unspecified')} · Imported content</small></span><span class="status ${x.status==='available'?'':'waiting'}">${esc(x.status)}</span></a>`).join('')}</div>`:''}<h2 class="section-title">Awaiting material</h2><div class="card"><p>Parts 3–5 (microstructure, execution bridges, compliance) remain in research. No progress can be earned on missing parts.</p><a class="button secondary small" href="#settings">Preview a lesson import</a></div>`}
function md(src){let out='',inList=false;for(const line of src.split('\n')){let s=line.trim();if(!s){if(inList){out+='</ul>';inList=false}continue}if(/^https?:/.test(s)){out+=`<p><a target="_blank" rel="noopener" href="${esc(s)}">${esc(s)}</a></p>`;continue}if(s.startsWith('# ')){out+=`<h1>${esc(s.slice(2))}</h1>`;continue}if(s.startsWith('## ')){out+=`<h2 id="${slug(s.slice(3))}">${esc(s.slice(3))}</h2>`;continue}if(s.startsWith('### ')){out+=`<h3>${esc(s.slice(4))}</h3>`;continue}if(s.startsWith('- ')){if(!inList){out+='<ul>';inList=true}out+=`<li>${inline(s.slice(2))}</li>`;continue}if(/^\d+\. /.test(s)){if(!inList){out+='<ol>';inList=true}out+=`<li>${inline(s.replace(/^\d+\. /,''))}</li>`;continue}if(inList){out+='</ul>';inList=false}out+=`<p>${inline(s)}</p>`}if(inList)out+='</ul>';return out}
function inline(s){return esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>')}
function slug(s){return s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function lesson(n){n=Math.max(1,Math.min(8,+n||1));state.lesson=n;if(!state.read.includes(n)){state.read.push(n);save()}let chunks=courseText.split(/(?=^## Lesson \d+ — )/m), full=chunks.find(c=>c.startsWith(`## Lesson ${n} —`))||'';full=full.split(/(?=^### )/m).filter(x=>!/^### (Quiz|Answers)\b/m.test(x.trim())).join('');let html=md(full);let heads=[...full.matchAll(/^### (.+)$/gm)].map(m=>m[1]);let missing=Array.from({length:Math.max(0,n-1)},(_,i)=>i+1).filter(i=>!state.mastered.includes(i));app.innerHTML=`<div class="page-head"><div class="eyebrow">PART ${n>4?'2':'1'} · LESSON ${n} OF 8</div><h1>${lessonTitle(n)}</h1><p>Work through the supplied course material below. Numerical price examples are hypothetical.</p><div class="actions"><button class="button secondary small" onclick="bookmark(${n})">${state.bookmarks.includes(n)?'★ Bookmarked':'☆ Bookmark'}</button><button class="button secondary small" onclick="markPractice(${n})">${state.practiced.includes(n)?'✓ Practiced':'Mark practiced'}</button></div></div>${missing.length?`<div class="notice">Prerequisite checkpoint${missing.length>1?'s':''} not yet marked mastered: ${missing.map(i=>`Lesson ${i}`).join(', ')}. You can continue or review earlier lessons.</div>`:''}<div class="lesson-layout"><article class="lesson-body">${html}<hr><h2>Personal notes</h2><textarea id="notes" class="search" placeholder="Your notes stay in this browser…" rows="5">${esc(state.notes[n]||'')}</textarea><div class="actions"><button class="button small" onclick="saveNote(${n})">Save notes</button><button class="button secondary small" onclick="quiz(${n})">Take lesson quiz</button><button class="button secondary small" onclick="markAssignment(${n})">${state.assignments.includes(n)?'✓ Assignment complete':'Mark assignment complete'}</button>${n===4?'<a class="button secondary small" href="#assessment">Part 1 assessment</a>':''}</div><div id="quiz"></div><h2>Mastery checkpoint</h2><p>Use the checkpoint in the supplied lesson text. Mastery is a learner attestation, not an automatic score.</p><div class="check-row"><input id="masterCheck" type="checkbox" ${state.mastered.includes(n)?'checked':''}><label for="masterCheck">I completed the checkpoint described above and can demonstrate the requested work.</label></div><button class="button small" onclick="master(${n})">Save mastery status</button></article><aside class="toc"><b class="tiny">ON THIS PAGE</b>${heads.map(h=>`<a href="#${slug(h)}">${esc(h)}</a>`).join('')}</aside></div><div class="actions"><a class="button secondary" href="#lesson/${Math.max(1,n-1)}">← Previous</a><a class="button" href="#lesson/${Math.min(8,n+1)}">Next lesson →</a></div>`}
function bookmark(n){state.bookmarks=state.bookmarks.includes(n)?state.bookmarks.filter(x=>x!==n):[...state.bookmarks,n];save();route()}
function markPractice(n){state.practiced=state.practiced.includes(n)?state.practiced:[...state.practiced,n];save();toast('Practice status saved');route()}
function markAssignment(n){state.assignments=state.assignments.includes(n)?state.assignments:[...state.assignments,n];save();toast('Assignment status saved');route()}
function saveNote(n){state.notes[n]=$('#notes').value;save();toast('Note saved on this device')}
const quizzes={1:[['A $1,000 linear position falls 2%. Price loss before costs?',['$2','$20','$200'],1,'2% × $1,000 = $20.'],['Does $100 margin automatically cap loss at $100?',['Yes','No'],1,'Liability and liquidation depend on product rules.'],['With quantity fixed, does changing the collateral ratio change linear price P/L?',['Yes','No'],1,'Price P/L depends on quantity and price movement in this model.']],2:[['Does futures margin purchase the underlying?',['Yes','No'],1,'It is collateral under the contract rules.'],['Four ticks at $1.25 each equal?',['$1.25','$5','$20'],1,'Four multiplied by $1.25 is $5.'],['Does a BTC chart establish withdrawal rights?',['Yes','No'],1,'Inspect product and account terms.']],3:[['Does a limit touch guarantee a fill?',['Yes','No'],1,'Queue position, liquidity and market changes matter.'],['Which stop order retains a price constraint after triggering?',['Stop-market','Stop-limit'],1,'A stop-limit becomes a limit order.'],['Average fill for 2 at $100.10 and 2 at $100.20?',['$100.10','$100.15','$100.20'],1,'Total $400.60 divided by 4 = $100.15.'],['After a timeout, repeat immediately?',['Yes','No; check status first'],1,'Verify order and exposure status to avoid duplicates.']],4:[['Is planned loss guaranteed?',['Yes','No'],1,'Gaps, costs and product mechanics can produce a larger loss.'],['What if the minimum order exceeds the permitted size?',['Increase budget','Reject or choose another product'],1,'Do not force the position by changing the budget.'],['Does reduced collateral change unchanged linear quantity’s price sensitivity?',['Yes','No'],1,'Not in the simple linear formula.']],5:[['In multi-asset momentum, does +50% return automatically outrank +20% return?',['Yes','No; risk-standardization and volatility matter','Yes, nominal gains always dominate'],1,'An asset with +50% gain may carry disproportionate volatility, yielding a lower risk-standardized score.'],['What does Ridge regression add to normal equations in RAPM?',['Zero penalty','An L2 penalty shrinking collinear coefficients toward zero','Random Gaussian noise'],1,'Ridge regression adds lambda * I to shrink noisy coefficients toward a prior of average performance.'],['Why is high rebalancing frequency toxic to memecoin rotation?',['Exchange rewards','Turnover friction, spread expansion, and pool swap fees compound rapidly','Memecoins have zero transaction costs'],1,'Friction and slippage eat gross alpha rapidly when rotating volatile, low-liquidity assets.']],6:[['What does negative return skewness (s < 0) indicate?',['Gains are larger than losses','Downside crashes are steeper and more severe than rallies','Returns follow a Gaussian bell curve'],1,'Negative skewness indicates an elongated left tail of sharp downside market crashes.'],['How does excess kurtosis (k > 0) affect the Cornish-Fisher quantile?',['No change','Pushes the critical value deeper into the adverse tail compared to normal z','Brings the quantile closer to zero'],1,'Fat tails expand the critical quantile, increasing estimated VaR to accurately capture outlier probability.'],['How does volatility targeting respond during a market crash?',['Borrows additional leverage','Scales down risky position weights (w = target / vol) to preserve capital','Freezes the browser'],1,'As volatility surges, the inverse-volatility sizing formula automatically reduces exposure.']],7:[['When a signal triggers at Bar 10 Close, at what price does a causality-safe backtest execute?',['Bar 10 Open','Bar 10 Close','Bar 11 Open'],2,'Executing at Bar 11 Open prevents lookahead bias because Bar 10 Close is only known after Bar 10 ends.'],['If an asset gaps overnight below your stop-market price, where does the order fill?',['At the exact stop price','At or near the next market open price (experiencing gap slippage)','The order is canceled'],1,'Stop-market orders trigger at market; overnight gaps execute at available opening market prices.'],['Why does the Vektor paper accounting engine use Decimal instead of float?',['Floats produce binary rounding errors that leak fractions of cents over repeated trades','Float is too slow','Decimal is required by exchange servers'],0,'Arbitrary-precision Decimal with banker rounding prevents accumulated penny precision drift.']],8:[['Why is random k-fold cross-validation prohibited in financial time series?',['It takes too much CPU','It allows future information and regimes to leak into past training bars','It requires GPU acceleration'],1,'Random shuffling leaks temporal autocorrelation and future market regimes into the training set.'],['What does the Vektor "sharpe_decay" flag detect?',['Test Sharpe is higher than Train Sharpe','Test Sharpe collapsed to less than half of Train Sharpe or is undefined','Sharpe ratio is 1.0'],1,'A collapse of over 50% in out-of-sample Sharpe ratio indicates severe parameter overfitting.'],['Why is an optimal parameter sitting at the edge of the grid a warning sign?',['The grid is too large','The search hit an artificial boundary constraint and may not represent a true stable interior peak','It confirms optimal performance'],1,'Edge-of-grid parameters often indicate parameter instability or an artificial corner solution.']]};
function quiz(n){let q=quizzes[n]||[];$('#quiz').innerHTML=`<h2>Lesson ${n} quiz</h2><form id="quizForm">${q.map((x,i)=>`<div class="quiz-item"><p>${i+1}. ${esc(x[0])}</p>${x[1].map((o,j)=>`<label><input type="radio" name="q${i}" value="${j}"> ${esc(o)}</label>`).join('')}<div class="answer" id="ans${i}">${esc(x[3])}</div></div>`).join('')}<button class="button small" type="button" onclick="grade(${n})">Submit answers</button> <button class="button secondary small" type="button" onclick="showAnswers(${n})">Reveal explanations</button><span id="score" class="tiny"></span></form>`;$('#quiz').scrollIntoView({behavior:'smooth',block:'start'})}
function grade(n){const q=quizzes[n],answers=q.map((_,i)=>{const v=document.querySelector(`input[name=q${i}]:checked`);return v?+v.value:-1}),result=AcademyMath.scoreQuiz(q.map(x=>x[2]),answers);q.forEach((_,i)=>$('#ans'+i).classList.add('show'));$('#score').textContent=` Score: ${result.score}/${result.total}.`;if(result.passed){state.passed=state.passed.includes(n)?state.passed:[...state.passed,n];save();toast('Quiz passed')}else toast('Review explanations and try again')}
function showAnswers(n){quizzes[n].forEach((_,i)=>$('#ans'+i).classList.add('show'))}
function master(n){if(!$('#masterCheck').checked){toast('Complete the checkpoint before recording mastery');return}state.mastered=state.mastered.includes(n)?state.mastered:[...state.mastered,n];save();toast('Mastery status recorded');route()}
const assessQ=[['Notional exposure for 0.020 BTC at $50,000?',['$100','$1,000','$10,000'],1],['Illustrative initial margin at the assumed 10:1 ratio?',['$10','$100','$1,000'],1],['Intended price loss from $50,000 to $49,500?',['$5','$10','$20'],1],['Realized net loss after an exit at $49,200 and $2 fees?',['$16','$18','$20'],1],['Equity drawdown on $1,000 from that $18 loss?',['0.18%','1.8%','18%'],1],['Does this information establish a liquidation price?',['Yes, $49,200','$100 is margin, so liquidation is $49,000','No; product/collateral/maintenance/reference rules are missing'],2]];
function assessment(){app.innerHTML=`<div class="page-head"><div class="eyebrow">PART 1 · FINAL CHECK</div><h1>Part 1 assessment</h1><p>Hypothetical case from the supplied course: $1,000 account equity; long 0.020 BTC at $50,000; assumed 10:1 notional-to-margin; intended stop $49,500; actual exit $49,200; total fees $2.</p></div><div class="notice">Pass requires all calculations and a clear distinction among margin, stop and maximum possible loss. Passing is not live-trading authorization.</div><div class="card"><form id="assessmentForm">${assessQ.map((q,i)=>`<div class="quiz-item"><p>${i+1}. ${esc(q[0])}</p>${q[1].map((o,j)=>`<label><input type="radio" name="aq${i}" value="${j}"> ${esc(o)}</label>`).join('')}<div class="answer" id="aa${i}"></div></div>`).join('')}<div class="field"><label for="assessmentReason">In your words, why can’t we infer liquidation from these inputs?</label><textarea id="assessmentReason" placeholder="Explain the missing product and collateral rules…"></textarea></div><div class="check-row"><input id="assessmentReview" type="checkbox"><label for="assessmentReview">I checked that my written explanation distinguishes assumed margin, the planned stop and the product-specific liquidation rules that are still unknown.</label></div><div class="actions"><button type="button" class="button" onclick="gradeAssessment()">Submit assessment</button><button type="button" class="button secondary" onclick="revealAssessment()">Reveal answers and explanations</button><span id="assessmentScore" class="tiny"></span></div></form></div>`}
function gradeAssessment(){let answers=assessQ.map((_,i)=>{const a=document.querySelector(`input[name=aq${i}]:checked`);return a?+a.value:-1}),result=AcademyMath.scoreQuiz(assessQ.map(x=>x[2]),answers);assessQ.forEach((q,i)=>{let ok=answers[i]===q[2];$('#aa'+i).textContent=ok?`Correct. ${['Notional is quantity × entry.','Illustrative margin is notional ÷ assumed ratio.','0.020 × ($50,000−$49,500) = $10.','0.020 × ($50,000−$49,200) = $16; plus $2 fees = $18.','($18 ÷ $1,000) × 100 = 1.8%.','No liquidation threshold follows without the actual product rules.'][i]}`:'Review the answer key and explanation.';$('#aa'+i).classList.add('show')});let reason=$('#assessmentReason').value.trim(),pass=result.passed&&reason.length>=20&&$('#assessmentReview').checked;$('#assessmentScore').textContent=` Score ${result.score}/${result.total}${pass?' · assessment passed':result.passed?' · review the liquidation explanation to record completion':' · try again after reviewing the explanations'}.`;state.assessmentPassed=!!pass;save();if(pass)toast('Part 1 assessment passed')}
function revealAssessment(){assessQ.forEach((q,i)=>{$('#aa'+i).textContent=['Notional = 0.020 × $50,000 = $1,000.','Illustrative margin = $1,000 ÷ 10 = $100.','Intended loss = 0.020 × ($50,000−$49,500) = $10.','Realized loss = 0.020 × ($50,000−$49,200) + $2 = $18.','Drawdown = $18 ÷ $1,000 = 1.8%.','Liquidation depends on actual contract, collateral, maintenance and reference-price rules; these values do not determine it.'][i];$('#aa'+i).classList.add('show')})}
function exposure(){app.innerHTML=`<div class="page-head"><div class="eyebrow">PRACTICE TOOL · LINEAR LONG MODEL</div><h1>Exposure explorer</h1><p>Change quantity and prices to see how exposure and price movement relate. This is a simple educational model, not a product quote.</p></div><div class="grid grid-2"><div class="card"><h3>Position assumptions</h3><div class="form-grid"><div class="field"><label for="equity">Account equity ($)</label><input id="equity" type="number" min="0.01" value="1000"></div><div class="field"><label for="entry">Entry price ($)</label><input id="entry" type="number" min="0.01" value="50000"></div><div class="field"><label for="qty">Quantity (BTC)</label><input id="qty" type="number" min="0.000001" step="0.001" value="0.02"></div><div class="field"><label for="ratio">Illustrative notional-to-margin ratio</label><input id="ratio" type="number" min="0.01" step="0.1" value="10"></div><div class="field"><label for="exit">Hypothetical exit price ($)</label><input id="exit" type="number" min="0" value="49200"></div><div class="field"><label for="fees">Total fees ($)</label><input id="fees" type="number" min="0" value="2"></div></div><button class="button" onclick="calcExposure()">Calculate</button></div><div class="card"><h3>Illustrative results</h3><div id="exposureResults" class="result-grid"></div><div class="formula">Notional = quantity × entry<br>Gross P/L = quantity × (exit − entry)<br>Net P/L = gross P/L − fees<br>Illustrative margin = notional ÷ assumed ratio</div><div class="notice warning">This model does not calculate liquidation and does not apply to every contract type.</div></div></div><h2 class="section-title">Same price move, different exposure</h2><div class="table-wrap"><table><thead><tr><th>Example</th><th>Quantity</th><th>Notional at $50,000</th><th>Loss at $49,500</th><th>What the number means</th></tr></thead><tbody><tr><td>$100 spot BTC purchase</td><td>0.002 BTC</td><td>$100</td><td>$1</td><td>Purchase value equals notional in this simplified spot example.</td></tr><tr><td>$1,000 linear exposure, assumed 10:1</td><td>0.020 BTC</td><td>$1,000</td><td>$10</td><td>$100 illustrative margin; margin does not set price sensitivity.</td></tr></tbody></table></div><div class="notice">Required Part 1 example: equity $1,000; 0.020 BTC at $50,000; assumed 10:1 notional-to-margin; stop $49,500; exit $49,200; fees $2. Expected: $1,000 notional, $100 illustrative margin, $10 intended loss, $18 realized net loss and 1.8% equity drawdown.</div>`;calcExposure()}
function calcExposure(){let v={equity:+$('#equity').value,entry:+$('#entry').value,quantity:+$('#qty').value,ratio:+$('#ratio').value,exit:+$('#exit').value,fees:+$('#fees').value},box=$('#exposureResults');try{let x=AcademyMath.exposure(v),rows=[['Notional exposure',cash(x.notional)],['Illustrative margin',cash(x.margin)],['Gross price P/L',cash(x.gross)],['Net P/L after fees',cash(x.net)],['P/L as % equity',fmt(x.pctEquity)+'%'],['Notional / equity',fmt(x.notionalToEquity)+'×'],['Notional / margin',fmt(x.notionalToMargin)+'×']];box.innerHTML=rows.map(([a,b])=>`<div class="result"><b>${b}</b><span>${a}</span></div>`).join('')}catch{box.innerHTML='<div class="notice warning">Enter positive equity, entry, quantity and ratio; exit and fees cannot be negative.</div>'}}
function sizing(){app.innerHTML=`<div class="page-head"><div class="eyebrow">PRACTICE TOOL · LONG LINEAR ONLY</div><h1>Risk-sizing worksheet</h1><p>Choose a loss budget first; the worksheet does not recommend a universal risk percentage. A planned loss is not a guaranteed maximum.</p></div><div class="grid grid-2"><div class="card"><div class="form-grid"><div class="field"><label>Account equity ($)</label><input id="se" type="number" value="1000"></div><div class="field"><label>Chosen loss budget ($)</label><input id="sb" type="number" value="10"></div><div class="field"><label>Entry ($)</label><input id="sp" type="number" value="50000"></div><div class="field"><label>Planned stop ($)</label><input id="ss" type="number" value="49500"></div><div class="field"><label>Variable cost / unit ($)</label><input id="sc" type="number" value="20"></div><div class="field"><label>Fixed costs ($)</label><input id="sf" type="number" value="0"></div><div class="field"><label>Quantity increment</label><input id="si" type="number" step="any" value="0.001"></div><div class="field"><label>Minimum order size</label><input id="sm" type="number" step="any" value="0.001"></div><div class="field"><label>Illustrative margin ratio (optional)</label><input id="sr" type="number" step="any" placeholder="e.g. 10"></div><div class="field"><label>Worse execution exit ($)</label><input id="sg" type="number" value="49000"></div></div><button class="button" onclick="calcSizing()">Calculate size</button></div><div class="card"><h3>Result</h3><div id="sizeResults"><p class="muted">Enter assumptions and calculate.</p></div><div class="formula">q = (loss budget − fixed costs) ÷ (entry − stop + variable cost/unit)<br>Rounded quantity = floor(q ÷ increment) × increment</div><p class="tiny muted">Supported model: long linear positions. Shorts, inverse contracts and options require separate formulas and validation.</p></div></div>`}
function calcSizing(){let [equity,budget,entry,stop,variableCost,fixedCost,increment,minSize,worseExit]=['se','sb','sp','ss','sc','sf','si','sm','sg'].map(id=>+$('#'+id).value),marginRatio=$('#sr').value===''?null:+$('#sr').value,x=AcademyMath.sizeLong({equity,budget,entry,stop,variableCost,fixedCost,increment,minSize,worseExit,marginRatio});if(x.errors.length){$('#sizeResults').innerHTML=`<div class="notice warning">${x.errors.map(esc).join('<br>')}</div>`;return}if(!x.fits){$('#sizeResults').innerHTML='<div class="notice warning"><b>Does not fit constraints.</b><br>Rounded quantity is below the minimum order size or zero. Do not increase the loss budget to force a minimum order.</div>';return}$('#sizeResults').innerHTML=`<div class="result-grid"><div class="result"><b>${fmt(x.quantity,6)}</b><span>Rounded quantity</span></div><div class="result"><b>${cash(x.notional)}</b><span>Notional</span></div><div class="result"><b>${cash(x.plannedLoss)}</b><span>Estimated planned loss incl. costs</span></div><div class="result"><b>${fmt(x.budgetPct)}%</b><span>Budget as % of equity</span></div><div class="result"><b>${cash(x.worseLoss)}</b><span>Worse-execution loss estimate</span></div>${x.margin?`<div class="result"><b>${cash(x.margin)}</b><span>Illustrative margin</span></div>`:''}</div><div class="notice">These are arithmetic outputs from the assumptions entered. They do not establish that a position is affordable, safe, or suitable.</div>`;state.lastSizing={equity,budget,entry,stop,variableCost,fixedCost,increment,minSize,quantity:x.quantity,notional:x.notional,plannedLoss:x.plannedLoss,worseExecutionLoss:x.worseLoss,marginRatio};save()}
const scenarios=[['Market order','You submit a market buy for 4 units. Offers: 2 at $100.10 and 3 at $100.20. Assume no book changes or competition. What is the average fill?',['$100.10','$100.15','$100.20'],1,'Two units cost $200.20 and two cost $200.40: $400.60 total / 4 = $100.15.'],['Limit order','A buy limit at $100.10 meets an offer of 2 units at that price. What can you conclude?',['All units fill at $100.10','At most those 2 units may be available under the assumptions','The order must fill eventually'],1,'A touch or displayed quantity does not guarantee your fill.'],['Gap through stop','You own 10 shares at $100 with a sell stop at $98. Next executable price is $90. Before costs, the loss is:',['$20','$80','$100'],2,'A stop-market order can fill at the next available price. 10 × ($100−$90) = $100.'],['Stop-limit','A sell stop-limit triggers at $98 with a $97 limit. Market gaps to $90. What can happen?',['Guaranteed sell at $90','The limit may remain unfilled','Automatic liquidation at $98'],1,'Once triggered, the limit can remain unfilled below its allowed price.'],['Partial fill','Your 10-unit order fills 3 units. What exposure should you treat as open?',['10 units','3 units','0 units'],1,'Track executed quantity and remaining order separately.'],['Rejected order','A buy order is rejected. What should you assume before reviewing order and position status?',['The position is definitely open','No new order has been accepted; verify status and exposure','Retry repeatedly'],1,'Rejections and positions should be recorded from confirmed platform status.'],['Cancellation with remaining position','A 10-share entry filled, then the protective exit order is canceled. What remains?',['No exposure','10 shares remain open unless another action closed them','The cancellation closes the shares'],1,'Canceling an order does not itself close an already-open position.'],['Uncertain status','Submission times out. What is the safe status-check step in this teaching scenario?',['Submit again immediately','Check order and position status before retrying','Assume rejected'],1,'A timeout does not reveal whether the request reached the venue.']];
function orders(){app.innerHTML=`<div class="page-head"><div class="eyebrow">HYPOTHETICAL SCENARIOS</div><h1>Order-type practice</h1><p>Predict the outcome before revealing the explanation. This simplified model is not a reconstruction of exchange matching or live execution.</p></div><div class="grid grid-2">${scenarios.map((s,i)=>`<div class="card"><span class="pill">SCENARIO ${i+1} · ${esc(s[0])}</span><h3 style="margin-top:12px">${esc(s[1])}</h3><div>${s[2].map((x,j)=>`<label class="check-row"><input type="radio" name="ord${i}" value="${j}"><span>${esc(x)}</span></label>`).join('')}</div><button class="button secondary small" onclick="revealOrder(${i})">Check answer</button><div id="ore${i}" class="answer"></div></div>`).join('')}</div>`}
function revealOrder(i){const s=scenarios[i],a=$('#ore'+i),v=document.querySelector(`input[name=ord${i}]:checked`);a.textContent=(v&&+v.value===s[3]?'Correct. ':'Review: ')+s[4];a.classList.add('show')}
const pretradeItems=['Paper/live label recorded?','Exact product and venue understood?','Eligibility verified?','Equity, notional, margin and loss budget separated?','Quantity checked?','Entry, stop, invalidation and exit written?','Costs and worse execution calculated?','Minimum size affordable?','Correlated exposure reviewed?','Session and triggers checked?','Order status and cancellation understood?','Emergency status-check method identified?','Unknown critical field means no trade.'];
function pretrade(){app.innerHTML=`<div class="page-head"><div class="eyebrow">SUPPLIED PART 1 CHECKLIST</div><h1>Pre-trade checklist</h1><p>Use for educational simulation and product research. Unknown critical details mean no trade in the course material.</p></div><div class="card">${pretradeItems.map((x,i)=>`<div class="check-row"><input id="pc${i}" type="checkbox"><label for="pc${i}">${esc(x)}</label></div>`).join('')}<div class="actions"><button class="button secondary small" onclick="document.querySelectorAll('[id^=pc]').forEach(x=>x.checked=false)">Clear checklist</button><span id="pretradeCount" class="tiny muted">Self-check only; it does not authorize a live trade.</span></div></div>`;document.querySelectorAll('[id^=pc]').forEach(x=>x.onchange=()=>{$('#pretradeCount').textContent=`${document.querySelectorAll('[id^=pc]:checked').length}/${pretradeItems.length} checked · checklist state is not saved.`})}
function paper(){let pos=paperPositions(),mv=pos.reduce((s,p)=>s+p.qty*p.price,0),up=pos.reduce((s,p)=>s+p.qty*(p.price-p.avg),0);app.innerHTML=`<div class="page-head"><div class="eyebrow">SIMULATION · NO BROKER CONNECTION</div><h1>Paper trading lab</h1><p>Practice recording a hypothetical stock trade and see how quantity, notional and price changes affect a portfolio. No orders are sent anywhere.</p></div><div class="notice warning"><b>Market data is not connected.</b> Your Yahoo API access method and endpoint are not identified yet. Prices below are editable practice assumptions, not current quotes. Use Yahoo Finance links to view its public pages; later we can connect an authorized feed through the app’s provider adapter after you share its documentation.</div><div class="grid grid-3"><div class="card"><div class="metric">${cash(state.equity)}</div><div class="metric-label">Starting paper equity</div></div><div class="card"><div class="metric">${cash(mv)}</div><div class="metric-label">Open notional at entered prices</div></div><div class="card"><div class="metric">${cash(up)}</div><div class="metric-label">Unrealized P/L estimate</div></div></div><h2 class="section-title">Watchlist · editable practice prices</h2><div class="grid grid-3">${state.watchlist.map((x,i)=>`<div class="card"><div class="row between"><h3>${esc(x.symbol)}</h3><a href="https://finance.yahoo.com/quote/${encodeURIComponent(x.symbol)}/" target="_blank" rel="noopener" class="tiny">Yahoo page ↗</a></div><div class="field"><label>Assumed price (USD)</label><input type="number" min="0.01" step="any" value="${esc(x.price)}" onchange="changePrice(${i},this.value)"></div><div class="actions"><button class="button small" onclick="paperOrder(${i},'buy')">Simulate buy</button><button class="button secondary small" onclick="paperOrder(${i},'sell')">Simulate sell</button></div></div>`).join('')}<div class="card"><h3>Add symbol</h3><div class="field"><label>Ticker</label><input id="newTicker" placeholder="e.g. MSFT" maxlength="15"></div><div class="field" style="margin-top:9px"><label>Practice price ($)</label><input id="newPrice" type="number" min="0.01" step="any" placeholder="Enter a hypothetical price"></div><button class="button small" style="margin-top:10px" onclick="addSymbol()">Add to watchlist</button></div></div><h2 class="section-title">Open simulated positions</h2><div class="card">${pos.length?`<div class="table-wrap"><table><thead><tr><th>Symbol</th><th>Quantity</th><th>Average cost</th><th>Practice price</th><th>Notional</th><th>Unrealized P/L</th></tr></thead><tbody>${pos.map(p=>`<tr><td>${esc(p.symbol)}</td><td>${fmt(p.qty,4)}</td><td>${cash(p.avg)}</td><td>${cash(p.price)}</td><td>${cash(p.qty*p.price)}</td><td>${cash(p.qty*(p.price-p.avg))}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No positions yet. Simulate a buy to practice.</div>'}</div><h2 class="section-title">Simulated order history</h2><div class="card">${state.paperTrades.length?`<div class="table-wrap"><table><thead><tr><th>Type</th><th>Symbol</th><th>Quantity</th><th>Practice price</th><th>Notional</th><th>Realized P/L</th></tr></thead><tbody>${state.paperTrades.slice().reverse().map(t=>`<tr><td>${esc(t.side.toUpperCase())}</td><td>${esc(t.symbol)}</td><td>${fmt(t.qty,4)}</td><td>${cash(t.price)}</td><td>${cash(t.qty*t.price)}</td><td>${cash(t.realized||0)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No simulated orders. Nothing will be routed or executed.</div>'}</div><div class="notice">Simplified long-only, no-fee paper model. It does not simulate bid/ask spreads, partial fills, taxes, dividends, market hours, buying-power rules or real execution. Your local portfolio is a learning aid, not a brokerage statement.</div>`}
function paperPositions(){let map={};for(let t of state.paperTrades){let p=map[t.symbol]||{symbol:t.symbol,qty:0,avg:0,realized:0};if(t.side==='buy'){p.avg=p.qty?((p.avg*p.qty+t.price*t.qty)/(p.qty+t.qty)):t.price;p.qty+=t.qty}else{let sell=Math.min(t.qty,p.qty);p.realized+=(t.price-p.avg)*sell;p.qty-=sell}map[t.symbol]=p}return Object.values(map).filter(p=>p.qty>1e-8).map(p=>({...p,price:state.watchlist.find(x=>x.symbol===p.symbol)?.price??p.avg}))}
function changePrice(i,v){let p=+v;if(!Number.isFinite(p)||p<=0){toast('Enter a positive practice price');return}state.watchlist[i].price=p;save();paper()}
function addSymbol(){let s=$('#newTicker').value.trim().toUpperCase(),p=+$('#newPrice').value;if(!/^[A-Z0-9.^=-]{1,15}$/.test(s)||!Number.isFinite(p)||p<=0){toast('Enter a ticker and positive practice price');return}if(state.watchlist.some(x=>x.symbol===s)){toast('Ticker is already on the watchlist');return}state.watchlist.push({symbol:s,price:p});save();paper()}
function paperOrder(i,side){let item=state.watchlist[i],q=+prompt(`Enter hypothetical share quantity to ${side} ${item.symbol} at the practice price ${cash(item.price)}:`);if(!Number.isFinite(q)||q<=0){toast('Enter a positive quantity');return}let p=paperPositions().find(x=>x.symbol===item.symbol);if(side==='sell'&&(!p||q>p.qty)){toast(`Sell quantity cannot exceed open simulated shares (${fmt(p?.qty||0,4)}).`);return}let realized=side==='sell'?(item.price-(p?.avg||item.price))*q:0;state.paperTrades.push({side,symbol:item.symbol,qty:q,price:item.price,realized,at:new Date().toISOString()});save();paper();toast(`Simulated ${side} recorded locally`)}
function csvParse(s){return s.trim().split(/\r?\n/).map(l=>l.split(',').map(x=>x.trim()))}
function journal(){const items=state.journal;app.innerHTML=`<div class="page-head"><div class="eyebrow">PRIVATE · LOCAL TO THIS BROWSER</div><h1>Trading journal</h1><p>Separate process quality from outcome. A winning result does not automatically mean the decision was good.</p></div><div class="toolbar"><button class="button" onclick="journalForm()">＋ Add entry</button><button class="button secondary" onclick="exportCsv('journal')">Export CSV</button><input class="search" id="jsearch" placeholder="Search symbol, setup, notes…" oninput="filterJournal()"></div><div class="card"><div id="journalRows">${journalTable(items)}</div></div>`}
function journalTable(items){if(!items.length)return '<div class="empty">No journal entries yet. Add an entry after a paper or live activity; label it clearly.</div>';return `<div class="table-wrap"><table><thead><tr><th>Paper/live</th><th>Date / symbol</th><th>Product</th><th>Quantity</th><th>Net P/L</th><th>Decision quality</th><th>Rule followed</th><th></th></tr></thead><tbody>${items.map((x,i)=>`<tr><td>${esc(x.paper_or_live)}</td><td>${esc(x.timestamp_timezone)}<br><b>${esc(x.symbol)}</b></td><td>${esc(x.product_type)}</td><td>${esc(x.quantity)}</td><td>${esc(x.net_pnl)}</td><td>${esc(x.decision_quality)}</td><td>${esc(x.rule_followed)}</td><td><button class="button secondary small" onclick="editJournal(${i})">Edit</button> <button class="button secondary small" onclick="deleteJournal(${i})">Delete</button></td></tr>`).join('')}</tbody></table></div>`}
const journalFields=['paper_or_live','timestamp_timezone','symbol','venue','product_type','setup_version','equity_before','entry_planned','entry_actual','quantity','notional','margin','stop_planned','exit_planned','exit_actual','gross_pnl','fees','funding_borrow_cost','net_pnl','planned_loss_budget','rule_followed','screenshot_reference','decision_quality','notes'];
function journalForm(i=-1){const x=i<0?{}:state.journal[i];app.innerHTML=`<div class="page-head"><div class="eyebrow">JOURNAL ENTRY</div><h1>${i<0?'Add':'Edit'} entry</h1><p>Fields follow the supplied CSV schema. This is a personal record, not a performance claim.</p></div><div class="card"><form id="jform" class="form-grid">${journalFields.map(f=>`<div class="field ${f==='notes'?'full':''}"><label>${f.replaceAll('_',' ')}</label>${f==='notes'?`<textarea aria-label="${f.replaceAll('_',' ')}" name="${f}">${esc(x[f]||'')}</textarea>`:f==='paper_or_live'?`<select aria-label="${f.replaceAll('_',' ')}" name="${f}"><option value="">Choose…</option><option ${x[f]==='paper'?'selected':''}>paper</option><option ${x[f]==='live'?'selected':''}>live</option></select>`:f==='rule_followed'?`<select aria-label="${f.replaceAll('_',' ')}" name="${f}"><option value="">Unknown / not recorded</option><option ${x[f]==='yes'?'selected':''}>yes</option><option ${x[f]==='no'?'selected':''}>no</option><option ${x[f]==='partial'?'selected':''}>partial</option></select>`:f==='decision_quality'?`<select aria-label="${f.replaceAll('_',' ')}" name="${f}"><option value="">Not rated</option><option ${x[f]==='good'?'selected':''}>good</option><option ${x[f]==='mixed'?'selected':''}>mixed</option><option ${x[f]==='poor'?'selected':''}>poor</option></select>`:`<input aria-label="${f.replaceAll('_',' ')}" name="${f}" value="${esc(x[f]||'')}" ${['equity_before','entry_planned','entry_actual','quantity','notional','margin','stop_planned','exit_planned','exit_actual','gross_pnl','fees','funding_borrow_cost','net_pnl','planned_loss_budget'].includes(f)?'type="number" step="any"':''}>`}</div>`).join('')}<div class="field full actions"><button class="button" type="submit">Save entry</button><a href="#journal" class="button secondary">Cancel</a></div></form></div>`;$('#jform').onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(e.target));if(i<0)state.journal.unshift(x);else state.journal[i]=x;save();location.hash='#journal';toast('Entry saved locally')}}
function editJournal(i){journalForm(i)}function deleteJournal(i){if(confirm('Delete this journal entry?')){state.journal.splice(i,1);save();journal()}}function filterJournal(){let q=$('#jsearch').value.toLowerCase();$('#journalRows').innerHTML=journalTable(state.journal.filter(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(q))))}
const passportFields=['symbol','venue','legal_product','settlement_asset','quantity_unit','multiplier','minimum_size','tick_size','tick_value','session_timezone','expiry','custody','initial_margin','maintenance_margin','liquidation_reference','deficit_liability','fees','eligibility','source_url','checked_date'];
function passport(){app.innerHTML=`<div class="page-head"><div class="eyebrow">PRODUCT DUE DILIGENCE</div><h1>Product passport</h1><p>Record the product and its rules before reading the chart. Unknown is an acceptable state; a risk-critical unknown is a reason to pause.</p></div><div class="toolbar"><button class="button" onclick="passportForm()">＋ New passport</button><button class="button secondary" onclick="exportCsv('passport')">Export CSV</button></div><div class="grid grid-2">${state.passport.length?state.passport.map((x,i)=>`<div class="card"><div class="row between"><h3>${esc(x.symbol||'Unnamed product')}</h3><button class="button secondary small" onclick="editPassport(${i})">Edit</button></div><p>${esc(x.venue||'Unknown venue')} · ${esc(x.legal_product||'Unknown product type')}</p><div class="notice ${['multiplier','minimum_size','tick_size','initial_margin','maintenance_margin','liquidation_reference','deficit_liability'].some(k=>!x[k])?'warning':''}">Risk-critical fields: ${['multiplier','minimum_size','tick_size','initial_margin','maintenance_margin','liquidation_reference','deficit_liability'].filter(k=>!x[k]).map(k=>k.replaceAll('_',' ')).join(', ')||'recorded'}.</div>${x.source_url?`<a href="${esc(x.source_url)}" target="_blank" rel="noopener">Source</a>`:''}</div>`).join(''):'<div class="card empty">No product passports yet. Unknown values will be retained as Unknown.</div>'}</div>`}
function passportForm(i=-1){let x=i<0?{}:state.passport[i];app.innerHTML=`<div class="page-head"><div class="eyebrow">EDITABLE TEMPLATE · FROM SUPPLIED CSV</div><h1>${i<0?'New':'Edit'} product passport</h1></div><div class="card"><form id="pform" class="form-grid">${passportFields.map(f=>`<div class="field"><label>${f.replaceAll('_',' ')}</label><input name="${f}" value="${esc(x[f]||'Unknown')}" placeholder="Unknown"></div>`).join('')}<div class="field full actions"><button class="button">Save passport</button><a class="button secondary" href="#passport">Cancel</a></div></form></div>`;$('#pform').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(i<0)state.passport.push(v);else state.passport[i]=v;save();location.hash='#passport';toast('Passport saved')}}function editPassport(i){passportForm(i)}
const strategyFields=['strategy_version','instrument_venue','timeframe_timezone','setup','entry_rule','stop_rule','exit_rule','sizing','no_trade_rules','regime_filter','data_source','development_period','validation_period','untouched_test_period','cost_model','slippage_model','benchmark','number_of_variants_tested','trade_count','net_expectancy','profit_factor','maximum_drawdown','rejection_criteria','remaining_uncertainty'];
function testing(){app.innerHTML=`<div class="page-head"><div class="eyebrow">RESEARCH WORKSPACE</div><h1>Strategy testing</h1><p>Workspace only. No strategy results, historical trades or backtests have been supplied, and none are fabricated here.</p></div><div class="notice warning">Strategy labs await full course source material. This is an empty testing worksheet, not a recommendation or evidence of an edge.</div><div class="toolbar"><button class="button" onclick="strategyForm()">＋ New strategy record</button><button class="button secondary" onclick="exportCsv('strategy')">Export CSV</button></div><div class="grid grid-2">${state.strategy.length?state.strategy.map((x,i)=>`<div class="card"><h3>${esc(x.strategy_version||'Unnamed strategy')}</h3><p>${esc(x.instrument_venue||'Market/venue unknown')} · ${esc(x.timeframe_timezone||'Timeframe unknown')}</p><button class="button secondary small" onclick="editStrategy(${i})">Edit record</button></div>`).join(''):'<div class="card empty">No strategy records. Fields are ready for source-backed definitions and evidence.</div>'}</div>`}
function strategyForm(i=-1){let x=i<0?{}:state.strategy[i];app.innerHTML=`<div class="page-head"><div class="eyebrow">STRATEGY TESTING WORKSHEET</div><h1>${i<0?'New':'Edit'} strategy record</h1></div><div class="card"><form id="tform" class="form-grid">${strategyFields.map(f=>`<div class="field ${['setup','entry_rule','stop_rule','exit_rule','no_trade_rules','remaining_uncertainty'].includes(f)?'full':''}"><label>${f.replaceAll('_',' ')}</label><textarea name="${f}" placeholder="Unknown / not supplied">${esc(x[f]||'')}</textarea></div>`).join('')}<div class="field full actions"><button class="button">Save</button><a class="button secondary" href="#testing">Cancel</a></div></form></div>`;$('#tform').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(i<0)state.strategy.push(v);else state.strategy[i]=v;save();location.hash='#testing'}}function editStrategy(i){strategyForm(i)}
const friendFields=['market','venue','legal_product','timeframe_timezone','setup','exact_entry_trigger','stop_invalidation','exit_rules','position_sizing','leverage','no_trade_conditions','claimed_performance','full_history_or_test_method','fees','slippage','screenshots_timestamps','missing_information'];
function friend(){app.innerHTML=`<div class="page-head"><div class="eyebrow">SUBMISSION INTAKE</div><h1>Friend-strategy review</h1><p>Capture the claim fairly and identify what evidence and rules are missing. This intake does not declare a strategy profitable or fraudulent.</p></div><div class="notice">The full review rubric is awaiting course material. This is an intake and review framework only.</div><div class="toolbar"><button class="button" onclick="friendForm()">＋ New submission</button><button class="button secondary" onclick="exportCsv('friend')">Export CSV</button></div><div class="grid grid-2">${state.friend.length?state.friend.map((x,i)=>`<div class="card"><h3>${esc(x.market||'Market unknown')} · ${esc(x.timeframe_timezone||'Timeframe unknown')}</h3><p>${esc(x.legal_product||'Product unknown')}</p><button class="button secondary small" onclick="editFriend(${i})">Open review</button></div>`).join(''):'<div class="card empty">No submissions. Add a strategy to generate a structured review record.</div>'}</div>`}
function friendForm(i=-1){let x=i<0?{}:state.friend[i];app.innerHTML=`<div class="page-head"><div class="eyebrow">STRUCTURED INTAKE</div><h1>${i<0?'New':'Edit'} strategy submission</h1></div><div class="card"><form id="fform" class="form-grid">${friendFields.map(f=>`<div class="field ${['setup','exact_entry_trigger','stop_invalidation','exit_rules','position_sizing','no_trade_conditions','claimed_performance','full_history_or_test_method','missing_information'].includes(f)?'full':''}"><label>${f.replaceAll('_',' ')}</label><textarea name="${f}" placeholder="Unknown / not provided">${esc(x[f]||'')}</textarea></div>`).join('')}<div class="field full"><h3>Review prompts</h3><p>Fair restatement · Missing rules · Plausible mechanism vs sales story · Untestable claims · Hidden leverage · Tail-risk questions · Proposed objective test · Evidence supporting or rejecting further tests.</p></div><div class="field full actions"><button class="button">Save intake</button><a class="button secondary" href="#friend">Cancel</a></div></form></div>`;$('#fform').onsubmit=e=>{e.preventDefault();let v=Object.fromEntries(new FormData(e.target));if(i<0)state.friend.push(v);else state.friend[i]=v;save();location.hash='#friend'}}function editFriend(i){friendForm(i)}
const resources=[['R1','How to trade with leverage in Paper Trading','TradingView','https://www.tradingview.com/support/solutions/43000742700-how-to-trade-with-leverage-in-paper-trading/','Public help article; leverage by asset class, order ticket margin details, account margin tracking. Platform subscription incentive.','Link verification carried forward; not rechecked during packaging. Simulation is not live custody.'],['R2','Margin: Know What’s Needed','CME Group','https://www.cmegroup.com/education/courses/introduction-to-futures/margin-know-what-is-needed','Public lesson on initial and maintenance margin. Futures-specific; exchange participation incentive.','Material verified in original research; no full embedded-media review claim.'],['R3','Introduction to Futures','CME Group','https://www.cmegroup.com/education/courses/introduction-to-futures','Public course: specs, expiry, settlement, ticks, notional and margin. Exchange commercial incentive.','Syllabus verified in original research; not all media reviewed.'],['R4','Micro E-mini Equity Index futures products overview','CME Group','https://www.cmegroup.com/education/courses/micro-e-mini-futures/micro-e-mini-futures-products-overview','Public lesson on multiplier/tick. Verify current specifications before use. Exchange commercial incentive.','Page material reported verified in original research.'],['R5','Types of Orders','SEC / Investor.gov','https://www.investor.gov/introduction-investing/investing-basics/how-stock-markets-work/types-orders','Free introductory article on market, limit and stop orders. Securities scope.','Page text retrieved in original research.'],['R6','Trading Up-Close: Stop and Stop-Limit Orders','Charles Schwab','https://www.youtube.com/watch?v=V-dnip2p3O4','Free YouTube video, 4:07. Transcript sections reported: 0:14 trigger; 0:41 stop-limit; 1:12 example; 2:43 continued-decline risk. Schwab account promotion.','Transcript retrieved in original research; visual inspection not performed.']];
function resourcePage(){app.innerHTML=`<div class="page-head"><div class="eyebrow">COURSE RESOURCES</div><h1>Resource library</h1><p>Verification states below are carried forward from the source file. Links have not been independently rechecked during package assembly; inclusion is not new verification.</p></div><div class="grid">${resources.map(r=>`<div class="card resource"><div><h3>${r[0]} · ${esc(r[1])}</h3><p>${esc(r[2])} · Free/public as described in source</p><p class="tiny">${esc(r[4])}</p><p class="tiny muted">${esc(r[5])}</p><a href="${esc(r[3])}" target="_blank" rel="noopener">Open source ↗</a></div><span class="pill">Carried forward</span></div>`).join('')}</div>`}
function glossary(){const terms=[['Equity','Account net value including open P/L.'],['Notional','Reference market exposure represented by a position.'],['Margin','Collateral supporting exposure or obligations under applicable rules.'],['Loss budget','Planned dollar constraint, not guaranteed maximum loss.'],['Long','Exposure benefiting from higher prices in the simple model used here.'],['Tick','Minimum permitted price increment.'],['Multiplier','Value represented by one contract price point.'],['Spread','Ask minus bid for the stated quotes.'],['Slippage','Actual execution versus a specified reference price.'],['Partial fill','Less than the full order quantity executed.'],['Initial margin','Required collateral to initiate a position.'],['Maintenance margin','Required collateral/equity to maintain a position.'],['Liquidation','Forced reduction or closure under applicable rules.'],['Unrealized P/L','Profit or loss while a position remains open.'],['Asset','An item or ownership interest.'],['Derivative','A contract linked to a reference.'],['Brokerage product','The actual legal and operational wrapper offered.'],['Exchange','An organization that arranges trading.'],['Broker','An intermediary handling customer orders.'],['Market maker','A participant that quotes prices and manages inventory.'],['Clearing','Processes settlement obligations under applicable rules.'],['Custody','How an asset is held.'],['Settlement','Completion of product obligations.'],['Expiry','Termination under product specifications.'],['Bid','A buying quote.'],['Ask','A selling quote.'],['Stop-market','Order that becomes a market order after its trigger.'],['Stop-limit','Order that becomes a limit order after its stop trigger.'],['Time in force','How long an order remains active under its instructions.']];app.innerHTML=`<div class="page-head"><div class="eyebrow">FIND A CONCEPT</div><h1>Glossary & search</h1><p>Definitions below are taken or lightly normalized from the supplied lesson explanations and starter glossary. No external verification is implied.</p></div><input id="gsearch" class="search" placeholder="Search glossary terms…" oninput="filterGlossary()"><div id="glossaryList" class="grid grid-2" style="margin-top:14px">${terms.map(t=>`<div class="card glossary-item"><span class="pill">COURSE-SUPPLIED</span><h3 style="margin-top:9px">${esc(t[0])}</h3><p>${esc(t[1])}</p></div>`).join('')}</div><h2 class="section-title">Search lessons and resources</h2><div class="toolbar"><input id="allSearch" class="search" placeholder="Search the course…" oninput="searchCourse()"></div><div id="searchResults"></div>`}
function filterGlossary(){let q=$('#gsearch').value.toLowerCase();document.querySelectorAll('.glossary-item').forEach(x=>x.style.display=x.textContent.toLowerCase().includes(q)?'':'none')}
function searchCourse(){let q=$('#allSearch').value.toLowerCase();if(!q){$('#searchResults').innerHTML='';return}let lines=courseText.split('\n'),found=[];lines.forEach((l,i)=>{if(l.toLowerCase().includes(q)&&l.trim())found.push(`<div class="card"><p>${esc(l.replace(/^#+\s*/,''))}</p><small class="muted">Part 1 course material · line ${i+1}</small></div>`)});$('#searchResults').innerHTML=found.slice(0,20).join('')||'<div class="empty">No matches.</div>'}
function study(){let items=[['a','Session A · 35–45 minutes','Read and reproduce examples in your own words.'],['b','Session B · 35–45 minutes','Complete the relevant worksheet and practice in simulation.'],['c','Session C · 35–45 minutes','Take the quiz without notes; reconcile errors.'],['review','Review · 45–60 minutes','Repeat failed checkpoints and review your notes.']];app.innerHTML=`<div class="page-head"><div class="eyebrow">FLEXIBLE ROUTINE</div><h1>Study planner</h1><p>Suggested routine from the course source. Adjust around school and rest; there are no streaks or countdowns. Advancement depends on mastery, not elapsed weeks.</p></div><div class="card">${items.map(([id,title,desc])=>`<div class="study-block row between"><div><h3>${title}</h3><p>${desc}</p></div><div class="field"><label for="plan-${id}">Optional date</label><input id="plan-${id}" type="date" value="${esc(state.studyPlan[id]||'')}" onchange="saveStudyPlan()"></div></div>`).join('')}<p class="tiny muted">You can change any date whenever you need. Moving a session has no penalty.</p><button class="button secondary small" onclick="document.querySelectorAll('[id^=plan-]').forEach(x=>x.value='');saveStudyPlan()">Clear dates</button></div><div class="notice">No fixed duration guarantees competence. Do not sacrifice sleep or school to keep pace.</div>`}
function saveStudyPlan(){document.querySelectorAll('[id^=plan-]').forEach(x=>state.studyPlan[x.id.replace('plan-','')]=x.value);save();toast('Schedule updated. Rescheduling has no penalty.')}
function customLessonPage(id){const x=state.customLessons.find(l=>l.id===decodeURIComponent(id));if(!x){app.innerHTML='<div class="empty">Imported lesson not found.</div>';return}app.innerHTML=`<div class="page-head"><div class="eyebrow">IMPORTED COURSE CONTENT · PART ${esc(x.part||'UNSPECIFIED')}</div><h1>${esc(x.title)}</h1><p><span class="status ${x.status==='available'?'':'waiting'}">${esc(x.status)}</span> · Imported content is shown as supplied and rendered as text.</p></div><article class="lesson-body">${md(x.content)}<div class="notice">Source file: ${esc(x.sourceFile||'user import')}. Imported text is escaped before display; external source verification is not inferred.</div></article><div class="actions"><a class="button secondary" href="#course">Back to course</a></div>`}
function settings(){app.innerHTML=`<div class="page-head"><div class="eyebrow">YOUR DATA</div><h1>Data & settings</h1><p>All progress, notes, journal entries and worksheets stay in this browser’s local storage. Browser data can be cleared by the browser or device settings. Export a backup to keep a copy.</p></div><div class="grid grid-2"><div class="card"><h3>Backup and restore</h3><p>Export the academy data as JSON. Restore validates the file shape before loading it.</p><div class="actions"><button class="button" onclick="backup()">Download JSON backup</button><button class="button secondary" onclick="$('#restoreFile').click()">Restore backup</button><input id="restoreFile" type="file" accept="application/json,.json" hidden onchange="restore(event)"></div></div><div class="card"><h3>Import future lessons</h3><p>Choose a JSON file and preview lesson titles and changes before adding it. Existing notes and progress are kept. HTML is not executed.</p><div class="actions"><button class="button secondary" onclick="$('#lessonImport').click()">Choose lesson JSON</button><input id="lessonImport" type="file" accept="application/json,.json" hidden onchange="previewLessonImport(event)"></div><div id="importPreview"></div></div><div class="card"><h3>Appearance</h3><p>Choose a comfortable reading theme.</p><button class="button secondary" onclick="toggleTheme()">Switch light / dark mode</button></div><div class="card"><h3>CSV exports</h3><p>Download journal, product passport, strategy-testing or friend-strategy records. Spreadsheet formula prefixes are escaped.</p><div class="actions"><button class="button secondary small" onclick="exportCsv('journal')">Journal</button><button class="button secondary small" onclick="exportCsv('passport')">Passport</button><button class="button secondary small" onclick="exportCsv('strategy')">Strategy</button><button class="button secondary small" onclick="exportCsv('friend')">Friend intake</button></div></div><div class="card"><h3>Reset local data</h3><p>This deletes progress, notes and entries from this browser.</p><button class="button danger" onclick="resetData()">Reset with confirmation</button></div></div><div class="notice warning">No analytics or personal data are sent to third parties by the application. External resource links open their source websites when selected.</div>`}
let pendingLessonImport=[];
function previewLessonImport(e){let f=e.target.files[0];if(!f)return;if(f.size>1024*1024){toast('Lesson import is limited to 1 MB');return}let rd=new FileReader();rd.onload=()=>{try{let j=JSON.parse(rd.result),ls=Array.isArray(j)?j:j.lessons;if(!Array.isArray(ls)||!ls.length||ls.length>100)throw Error();for(let x of ls)if(!x||!/^[a-z0-9][a-z0-9_-]{0,63}$/i.test(x.id)||typeof x.title!=='string'||!x.title.trim()||typeof x.content!=='string'||!['available','awaiting material'].includes(x.status||'available'))throw Error();pendingLessonImport=ls.map(x=>({...x,status:x.status||'available',sourceFile:f.name}));$('#importPreview').innerHTML=`<div class="notice">Preview: ${pendingLessonImport.length} lesson(s). Existing IDs will have content/metadata updated; notes and progress are stored separately and will be kept.<ul>${pendingLessonImport.map(x=>`<li><b>${esc(x.title)}</b> · ${esc(x.status)} · ${state.customLessons.some(y=>y.id===x.id)?'Update existing':'New lesson'}</li>`).join('')}</ul><button class="button small" onclick="applyLessonImport()">Apply imported lessons</button></div>`}catch{$('#importPreview').innerHTML='<div class="notice warning">Invalid JSON lesson package. Each lesson needs id, title, content; optional part, stage, status. Max 100 lessons, 1 MB.</div>'}finally{e.target.value=''}};rd.readAsText(f)}
function applyLessonImport(){if(!pendingLessonImport.length){toast('Preview a valid lesson file first');return}let map=new Map(state.customLessons.map(x=>[x.id,x]));pendingLessonImport.forEach(x=>map.set(x.id,{...map.get(x.id),...x}));state.customLessons=[...map.values()];save();pendingLessonImport=[];toast('Lessons imported; notes and progress remain intact');route()}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark';save();toast('Theme updated')}
function backup(){let blob=new Blob([JSON.stringify({version:AcademyMath.BACKUP_VERSION,exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json'});download(blob,'trading-research-academy-backup.json')}
function restore(e){let f=e.target.files[0];if(!f)return;if(f.size>5*1024*1024){toast('Backup is too large (5 MB maximum)');e.target.value='';return}let reader=new FileReader();reader.onload=()=>{try{let o=AcademyMath.migrateBackup(JSON.parse(reader.result));if(!AcademyMath.validateBackup(o))throw Error('Invalid format');state=AcademyMath.loadState({getItem:()=>JSON.stringify(o.data)},KEY,initial);save();toast('Backup restored');route()}catch(err){toast('Backup not restored: invalid file')}finally{e.target.value=''}};reader.readAsText(f)}
function resetData(){if(confirm('Reset all Trading Research Academy data in this browser? This cannot be undone unless you have a backup.')){localStorage.removeItem(KEY);state=AcademyMath.loadState({getItem:()=>null},KEY,initial);save();route();toast('Local data reset')}}
function escapeCsv(x){let s=String(x??'');if(!/^-?\d+(?:\.\d+)?(?:e[+-]?\d+)?$/i.test(s)&&/^[=+\-@\t\r]/.test(s))s="'"+s;return `"${s.replaceAll('"','""')}"`}
function exportCsv(kind){const schemas={journal:journalFields,passport:passportFields,strategy:strategyFields,friend:friendFields},data=state[kind]||[];let rows=[schemas[kind],...data.map(x=>schemas[kind].map(k=>x[k]??''))],csv=rows.map(r=>r.map(escapeCsv).join(',')).join('\r\n');download(new Blob([csv],{type:'text/csv;charset=utf-8'}),`${kind}.csv`)}
function download(blob,name){let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('#themeButton').onclick=toggleTheme;$('#menuButton').onclick=()=>{$('#sidebar').classList.toggle('open');let o=$('.mobile-overlay')||document.body.appendChild(Object.assign(document.createElement('div'),{className:'mobile-overlay'}));o.classList.toggle('show');o.onclick=()=>{$('#sidebar').classList.remove('open');o.classList.remove('show')}};
init();
